// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address owner_, address debt_) public {
        // Both addresses must differ so the two arg words encode distinct values.
        vm.assume(owner_ != debt_);
        vm.assume(uint256(uint160(owner_)) < type(uint160).max);
        vm.assume(uint256(uint160(debt_)) < type(uint160).max);

        // Build clone-style calldata: selector for owner() plus packed immutable
        // args (owner, collateral, debt, factory) plus 2-byte extraLength = 80.
        bytes memory payload = abi.encodePacked(
            bytes4(keccak256("owner()")),
            owner_,
            address(0x1),
            debt_,
            address(0x2),
            uint16(80)
        );

        (bool ok, bytes memory ret) = address(c).call(payload);
        assertTrue(ok, "owner() call failed");
        assertTrue(ret.length == 32, "bad returndata");
        address returned = abi.decode(ret, (address));

        // General rule: owner() always returns the address stored at immutable-args offset 0x0.
        assertTrue(returned == owner_, "owner() must return the owner arg at offset 0x0");
    }
}
